#include "stdafx.h"#include "HcdElementBase.h"struct SSW_P{#include "PrivateVars/SW.h"};class KSW : public KHcdElementBase  , protected SSW_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _SW("SW", KSW::Create);IHcdElement *KSW::Create(){  return new KSW;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KSW, 4 )void KSW::InitParm(){#include "PrivateVars/SW.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KSW::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KSW::StepCalc( SStepCalcParams &params ){  if( SY )    OUTD0 = Y;  else    OUTD0 = INU0;}